112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
115	        Collection<Owner> owners;
116	        if (lastName != null) {
117	            owners = this.clinicService.findOwnerByLastName(lastName);
118	        } else {
119	            owners = this.clinicService.findAllOwners();
120	        }
121	        if (owners.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        Map<String, Integer> householdSizes = householdSizes();
125	        List<OwnerDto> ownerDtos = new java.util.ArrayList<>();
126	        for (Owner owner : owners) {
127	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
128	            applyMembership(ownerDto, owner, householdSizes);
129	            ownerDtos.add(ownerDto);
130	        }
131	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
142	        applyMembership(ownerDto, owner);
143	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
144	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
145	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        HttpHeaders headers = new HttpHeaders();
152	        String idempotencyKey = currentIdempotencyKey();
153	        if (idempotencyKey != null) {
154	            Integer existingId = idempotentCreates.get(idempotencyKey);
155	            if (existingId != null) {
156	                Owner existing = this.clinicService.findOwnerById(existingId);
157	                if (existing != null) {
158	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
159	                    applyMembership(existingDto, existing);
160	                    existingDto.setBulkSignupWarning(isBulkSignupDay());
161	                    existingDto.setCapacityWarning(isApproachingCapacity(existing.getCity()));
162	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
163	                }
164	            }
165	        }
166	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
167	        String address = applyAddress(owner, ownerFieldsDto);
168	        if (address.isEmpty()) {
169	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
170	        }
171	        owner.setAddress(address);
172	        String telephone = toE164(owner.getTelephone());
173	        if (telephone == null) {
174	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
175	        }
176	        owner.setTelephone(telephone);
177	        if (owner.getEmail() != null) {
178	            String email = normalizeEmail(owner.getEmail());
179	            if (email == null) {
180	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
181	            }
182	            owner.setEmail(email);
183	        }
184	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
185	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
186	        }
187	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
188	        if (effectiveRegistrationDate == null) {
189	            effectiveRegistrationDate = LocalDate.now();
190	        }
191	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
192	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
193	        }
194	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
195	        owner.setRegistrationDate(registrationDate);
196	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
197	            return new ResponseEntity<>(HttpStatus.CONFLICT);
198	        }
199	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
200	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
201	        }
202	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
203	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
204	        // share the household automatically. An owner without a postcode has no household.
205	        boolean declaredHouseholdMember = false;
206	        if (owner.getPostcode() != null) {
207	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
208	            owner.setHouseholdId(householdId);
209	            // A second owner sharing a household (same lastName + postcode) but with a distinct
210	            // identity is a legitimate additional household member — true duplicates are still
211	            // caught by the identityKey check below. 'sharesHousehold' opts such an owner in as a
212	            // declared member so it is not additionally flagged as a possible duplicate.
213	            boolean householdOccupied = false;
214	            for (Owner existing : this.clinicService.findAllOwners()) {
215	                if (existing.isDeleted()) {
216	                    continue;
217	                }
218	                if (householdId.equals(computeHouseholdId(existing))) {
219	                    householdOccupied = true;
220	                    break;
221	                }
222	            }
223	            if (householdOccupied && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
224	                declaredHouseholdMember = true;
225	            }
226	        }
227	        // Consolidated duplicate detection: reject only when the whole identityKey
228	        // (SHA-256 over normalizedTelephone | lowerEmail | soundex(lastName)) matches an
229	        // existing owner's. This is the single duplicate check; owners sharing a household
230	        // (same last name and postcode) but with different telephones produce different keys
231	        // and are no longer rejected here — they surface as soft matches below.
232	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
233	        for (Owner existing : this.clinicService.findAllOwners()) {
234	            if (existing.isDeleted()) {
235	                continue;
236	            }
237	            if (identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
238	                existing.getEmail(), existing.getLastName()))) {
239	                return new ResponseEntity<>(HttpStatus.CONFLICT);
240	            }
241	        }
242	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
243	        // existing owner's last name and postcode while having a different normalized
244	        // telephone it is still created and flagged as a possible duplicate of that owner. A
245	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
246	        if (declaredHouseholdMember) {
247	            owner.setPossibleDuplicate(false);
248	        }
249	        else {
250	            applyPossibleDuplicate(owner);
251	        }
252	        owner.setCustomerCode(deduplicatedCustomerCode(
253	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
254	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
255	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
256	        this.clinicService.saveOwner(owner);
257	        if (idempotencyKey != null) {
258	            idempotentCreates.put(idempotencyKey, owner.getId());
259	        }
260	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
261	        Map<String, Integer> householdSizes = householdSizes();
262	        applyMembership(ownerDto, owner, householdSizes);
263	        capMembershipLevelToHousehold(ownerDto, owner, householdSizes);
264	        applyOwnerSegment(ownerDto);
265	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
266	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
267	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
268	        emitOwnerCreatedEvent(owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
269	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
270	        ownerDto.setCapacityWarning(isApproachingCapacity(owner.getCity()));
271	        headers.setLocation(UriComponentsBuilder.newInstance()
272	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
273	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
274	    }
275	
276	    /**
277	     * The owner's current primary identifier, as carried by the structured {@code OWNER_CREATED}
278	     * event. Today that is the {@link Owner#getCustomerCode() customerCode}; when the customer code
279	     * is later unified into the member id this is the single place that switches to the member id,
280	     * so the event automatically carries whatever the current primary identifier is.
281	     *
282	     * @param owner the newly created, saved owner
283	     * @return the owner's current primary identifier
284	     */
285	    private static String primaryIdentifier(Owner owner) {
286	        return owner.getCustomerCode();
287	    }
288	
289	    /**
290	     * Emits the immutable, structured {@code OWNER_CREATED} audit event via the {@code AUDIT}
291	     * logger, in addition to the human-readable audit line. The event is a JSON object
292	     * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}} where {@code seq}
293	     * is a process-wide monotonically increasing integer across creates, and the {@code customerCode}
294	     * slot carries the owner's {@link #primaryIdentifier current primary identifier}.
295	     *
296	     * @param ownerId         the newly created owner's id
297	     * @param primaryId       the owner's current primary identifier (customerCode today)
298	     * @param membershipLevel the owner's resolved membership level
299	     */
300	    private static void emitOwnerCreatedEvent(int ownerId, String primaryId, int membershipLevel) {
301	        long seq = AUDIT_EVENT_SEQ.incrementAndGet();
302	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"customerCode\":\"{}\",\"membershipLevel\":{},"
303	            + "\"event\":\"OWNER_CREATED\"}", seq, ownerId, primaryId, membershipLevel);
304	    }
305	
306	    /**
307	     * Reads the {@code Idempotency-Key} header of the request currently being handled, used to make
308	     * owner creation idempotent. Returns the trimmed key when present and non-blank, otherwise
309	     * {@code null} (including when there is no active servlet request), so a missing or blank key
310	     * simply means "no idempotency" and the create proceeds normally.
311	     *
312	     * @return the current request's idempotency key, or {@code null} when none is supplied
313	     */
314	    private static String currentIdempotencyKey() {
315	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
316	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
317	            return null;
318	        }
319	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
320	        if (key == null || key.isBlank()) {
321	            return null;
322	        }
323	        return key.trim();
324	    }
325	
326	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
327	    @Override
328	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
329	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
330	        if (currentOwner == null) {
331	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
332	        }
333	        currentOwner.setAddress(ownerFieldsDto.getAddress());
334	        currentOwner.setCity(ownerFieldsDto.getCity());
335	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
336	        currentOwner.setLastName(ownerFieldsDto.getLastName());
337	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
338	        this.clinicService.saveOwner(currentOwner);
339	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
340	    }
341	
342	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
343	    @Transactional
344	    @Override
345	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
346	        Owner owner = this.clinicService.findOwnerById(ownerId);
347	        if (owner == null) {
348	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
349	        }
350	        // Soft delete: the row is retained and flagged deleted rather than removed, so the
351	        // owner is still readable via GET but is ignored by the create duplicate/identity checks.
352	        owner.setDeleted(true);
353	        this.clinicService.saveOwner(owner);
354	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
355	    }
356	
