421	
422	    /**
423	     * The maximum number of owners permitted per city. Owner creation is rejected once the
424	     * owner's city already contains this many owners.
425	     */
426	    private static final int MAX_OWNERS_PER_CITY = 50;
427	
428	    /**
429	     * Counts how many existing owners live in the given city, compared case-insensitively.
430	     * This is evaluated before the new owner is persisted, so the owner being created is not
431	     * included in the count.
432	     *
433	     * @param city the new owner's city
434	     * @return the number of existing owners in that city
435	     */
436	    private int countOwnersInCity(String city) {
437	        int count = 0;
438	        for (Owner existing : this.clinicService.findAllOwners()) {
439	            if (city.equalsIgnoreCase(existing.getCity())) {
440	                count++;
441	            }
442	        }
443	        return count;
444	    }
445	
446	    /**
447	     * The number of owners in a city at or above which a capacity warning is raised. Once the
448	     * owner's city holds at least this many owners (but is still below {@link #MAX_OWNERS_PER_CITY},
449	     * the hard limit), the city is approaching capacity and {@code capacityWarning} is reported as
450	     * {@code true} in the owner response.
451	     */
452	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
453	
454	    /**
455	     * Reports whether the given city is approaching the per-city capacity limit, i.e. whether it
456	     * already holds between {@link #CAPACITY_WARNING_THRESHOLD} (40) and
457	     * {@link #MAX_OWNERS_PER_CITY} minus one (49) owners inclusive. At the hard limit of 50 the
458	     * create is rejected outright, so a full city never warns.
459	     *
460	     * @param city the owner's city
461	     * @return {@code true} when the city holds 40-49 owners, otherwise {@code false}
462	     */
463	    private boolean isApproachingCapacity(String city) {
464	        int count = countOwnersInCity(city);
465	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
466	    }
467	
468	    /**
469	     * The maximum number of owners that may be created in a single business day. Owner
470	     * creation is rejected once this many owners already fall on the new owner's adjusted
471	     * business day {@code registrationDate}.
472	     */
473	    private static final int MAX_OWNERS_PER_DAY = 100;
474	
475	    /**
476	     * The fixed list of public holidays that the business-day roll skips over. A date that
477	     * lands on one of these is rolled forward to the next non-holiday business day.
478	     */
479	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
480	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
481	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
482	        LocalDate.parse("2026-12-28"));
483	
484	    /**
485	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
486	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
487	     * while a date that is already a non-holiday weekday is returned unchanged.
488	     *
489	     * @param date the date to adjust
490	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
491	     */
492	    private LocalDate toBusinessDay(LocalDate date) {
493	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
494	                || PUBLIC_HOLIDAYS.contains(date)) {
495	            date = date.plusDays(1);
496	        }
497	        return date;
498	    }
499	
500	    /**
501	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
502	     * registrationDate} rolls forward to the same business day. This is evaluated before the
503	     * new owner is persisted, so the owner being created is not included in the count.
504	     *
505	     * @param businessDay the adjusted business day to count against
506	     * @return the number of existing owners registered on that business day
507	     */
508	    private int countOwnersRegisteredOn(LocalDate businessDay) {
509	        int count = 0;
510	        for (Owner existing : this.clinicService.findAllOwners()) {
511	            LocalDate existingDate = existing.getRegistrationDate();
512	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
513	                count++;
514	            }
515	        }
516	        return count;
517	    }
518	
519	    /**
