537	    /**
538	     * Builds the customer code for a newly created owner, formatted
539	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
540	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
541	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
542	     * first eight upper-case hex characters of the SHA-256 digest of
543	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
544	     * stable for a given telephone and last name rather than dependent on creation order.
545	     *
546	     * @param postcode            the owner's postcode (may be {@code null})
547	     * @param normalizedTelephone the owner's normalized E.164 telephone
548	     * @param lastName            the owner's last name
549	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
550	     */
551	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
552	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
553	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
554	    }
