556	    /**
557	     * De-duplicates a freshly computed {@code base} customer code against the codes already
558	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
559	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
560	     * yields a code no existing owner holds.
561	     *
562	     * @param base the computed {@code '<REGION>-<HASH8>'} customer code
563	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
564	     */
565	    private String deduplicatedCustomerCode(String base) {
566	        Set<String> existing = new HashSet<>();
567	        for (Owner owner : this.clinicService.findAllOwners()) {
568	            if (owner.getCustomerCode() != null) {
569	                existing.add(owner.getCustomerCode());
570	            }
571	        }
572	        if (!existing.contains(base)) {
573	            return base;
574	        }
575	        int n = 2;
576	        while (existing.contains(base + "-" + n)) {
577	            n++;
578	        }
579	        return base + "-" + n;
580	    }
