582	    /**
583	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
584	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
585	     *
586	     * @param source the string to hash
587	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
588	     */
589	    private static String sha256Hex8(String source) {
590	        try {
591	            byte[] digest = MessageDigest.getInstance("SHA-256")
592	                .digest(source.getBytes(StandardCharsets.UTF_8));
593	            StringBuilder hex = new StringBuilder(digest.length * 2);
594	            for (byte b : digest) {
595	                hex.append(String.format("%02x", b));
596	            }
597	            return hex.substring(0, 8).toUpperCase();
598	        } catch (NoSuchAlgorithmException e) {
599	            throw new IllegalStateException("SHA-256 not available", e);
600	        }
601	    }
