639	    /**
640	     * Canonical expansions applied to common street-type abbreviations during address
641	     * normalization. Keys and values are upper-cased so the lookup runs after the address
642	     * has itself been upper-cased.
643	     */
644	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
645	        "ST", "STREET",
646	        "RD", "ROAD",
647	        "AVE", "AVENUE");
648	
649	    /**
650	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
651	     * every run of internal whitespace is collapsed to a single space, the result is
652	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
653	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
654	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
655	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
656	     * returned and compared for household duplicates; an address that is blank once
657	     * normalized fails the required-field check.
658	     *
659	     * @param address the raw address value supplied by the client
660	     * @return the normalized address (empty string when {@code address} is null or blank)
661	     */
662	    /**
663	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
664	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
665	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
666	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
667	     * address returned is the normalized {@code addressLine1} with a single space and the
668	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
669	     * the flat {@code address} is normalized and returned, and the structured lines are left
670	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
671	     * downstream (household hash, postcode validation and locality); an owner that supplies
672	     * neither form yields an empty string, failing the required-address check.
673	     *
674	     * @param owner          the owner being created, whose structured address lines are set here
675	     * @param ownerFieldsDto the submitted owner fields
676	     * @return the composed, normalized address (empty string when no address form is supplied)
677	     */
678	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
679	        String addressLine1 = ownerFieldsDto.getAddressLine1();
680	        if (addressLine1 != null && !addressLine1.isBlank()) {
681	            String normalizedLine1 = normalizeAddress(addressLine1);
682	            owner.setAddressLine1(normalizedLine1);
683	            String addressLine2 = ownerFieldsDto.getAddressLine2();
684	            if (addressLine2 != null && !addressLine2.isBlank()) {
685	                String normalizedLine2 = normalizeAddress(addressLine2);
686	                owner.setAddressLine2(normalizedLine2);
687	                return normalizedLine1 + " " + normalizedLine2;
688	            }
689	            owner.setAddressLine2(null);
690	            return normalizedLine1;
691	        }
692	        owner.setAddressLine1(null);
693	        owner.setAddressLine2(null);
694	        return normalizeAddress(ownerFieldsDto.getAddress());
695	    }
696	
697	    private static String normalizeAddress(String address) {
698	        if (address == null) {
699	            return "";
700	        }
701	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
702	        if (collapsed.isEmpty()) {
703	            return "";
704	        }
705	        StringBuilder normalized = new StringBuilder(collapsed.length());
706	        for (String token : collapsed.split(" ")) {
707	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
708	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
709	            if (normalized.length() > 0) {
710	                normalized.append(' ');
711	            }
712	            normalized.append(expanded != null ? expanded : token);
713	        }
714	        return normalized.toString();
715	    }
