717	    /**
718	     * Normalizes a last name or address for household-duplicate comparison: leading and
719	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
720	     * single space and the result is lower-cased. Two owners are considered to share a
721	     * household when both their last names and addresses produce the same key.
722	     *
723	     * @param value the raw last name or address value
724	     * @return the normalized comparison key (empty string when {@code value} is null)
725	     */
726	    private static String householdKey(String value) {
727	        if (value == null) {
728	            return "";
729	        }
730	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
731	    }
