733	    /**
734	     * Derives the stable shared household identifier for the given normalized last name key
735	     * and postcode. The identifier is deterministic — the same household (same
736	     * {@link #householdKey normalized} last name and postcode) always maps to the same
737	     * value — so every owner in a household is assigned an identical id. It is the
738	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
739	     * '<lastNameKey>|<postcode>'}.
740	     *
741	     * @param lastNameKey the normalized last name key
742	     * @param postcode    the owner's postcode
743	     * @return the shared household identifier
744	     */
745	    private static String householdId(String lastNameKey, String postcode) {
746	        String source = lastNameKey + "|" + postcode;
747	        try {
748	            byte[] digest = MessageDigest.getInstance("SHA-256")
749	                .digest(source.getBytes(StandardCharsets.UTF_8));
750	            StringBuilder hex = new StringBuilder(digest.length * 2);
751	            for (byte b : digest) {
752	                hex.append(String.format("%02x", b));
753	            }
754	            return hex.substring(0, 12).toUpperCase();
755	        } catch (NoSuchAlgorithmException e) {
756	            throw new IllegalStateException("SHA-256 not available", e);
757	        }
758	    }
