790	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
791	     * dto using a pre-computed map of household id to member count.
792	     *
793	     * @param ownerDto       the dto to populate
794	     * @param owner          the owner being mapped
795	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
796	     */
797	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
798	        int householdSize = owner.getHouseholdId() == null ? 1
799	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
