821	    /**
822	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
823	     * {@code membershipLevel} among the other current members of its household, writing the
824	     * capped value back onto the dto and returning it. A member's current level is scored the
825	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
826	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
827	     * has no household, or is the only member of its household, no cap applies and the level is
828	     * returned unchanged.
829	     *
830	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
831	     * @param owner          the newly created owner (already saved, so it has an id)
832	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
833	     * @return the resulting (possibly capped) membership level
834	     */
835	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
836	        Map<String, Integer> householdSizes) {
837	        int level = ownerDto.getMembershipLevel();
838	        String householdId = owner.getHouseholdId();
839	        if (householdId == null) {
840	            return level;
841	        }
842	        Integer maxMemberLevel = null;
843	        for (Owner existing : this.clinicService.findAllOwners()) {
844	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
845	                continue;
846	            }
847	            if (householdId.equals(existing.getHouseholdId())) {
848	                int size = householdSizes.getOrDefault(householdId, 1);
849	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
850	                maxMemberLevel = maxMemberLevel == null ? memberLevel
851	                    : Math.max(maxMemberLevel, memberLevel);
852	            }
853	        }
854	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
855	            level = maxMemberLevel + 1;
856	            ownerDto.setMembershipLevel(level);
857	        }
858	        return level;
859	    }
