861	    /**
862	     * Counts how many owners belong to each household, keyed by household id. Owners without a
863	     * household id (no postcode) are excluded — such an owner is its own single-member household.
864	     *
865	     * @return a map from household id to the number of owners sharing it
866	     */
867	    private Map<String, Integer> householdSizes() {
868	        Map<String, Integer> sizes = new java.util.HashMap<>();
869	        for (Owner existing : this.clinicService.findAllOwners()) {
870	            String householdId = existing.getHouseholdId();
871	            if (householdId != null) {
872	                sizes.merge(householdId, 1, Integer::sum);
873	            }
874	        }
875	        return sizes;
