878	    /**
879	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
880	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
881	     * possible duplicate when a non-deleted existing owner shares its {@link
882	     * OwnerIdentity#soundex soundex(lastName)} and its postcode while producing a different
883	     * {@code identityKey}; {@code possibleDuplicateOf} is then set to that existing owner's id.
884	     * Because the telephone is part of the identity key, two owners with the same last name and
885	     * postcode but different telephones differ in their keys and so surface here as a soft match
886	     * rather than a hard duplicate. When several existing owners match, the one with the lowest
887	     * id is chosen so the result is deterministic. When no such owner exists — or the new owner
888	     * has no postcode to compare — {@code possibleDuplicate} is set to {@code false} and no
889	     * matching id is recorded.
890	     *
891	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
892	     */
893	    private void applyPossibleDuplicate(Owner owner) {
894	        owner.setPossibleDuplicate(false);
895	        if (owner.getPostcode() == null) {
896	            return;
897	        }
898	        String soundex = OwnerIdentity.soundex(owner.getLastName());
899	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
900	        Owner match = null;
901	        for (Owner existing : this.clinicService.findAllOwners()) {
902	            if (existing.isDeleted()) {
903	                continue;
904	            }
905	            if (soundex.equals(OwnerIdentity.soundex(existing.getLastName()))
906	                && owner.getPostcode().equals(existing.getPostcode())
907	                && !identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
908	                    existing.getEmail(), existing.getLastName()))) {
909	                if (match == null || (existing.getId() != null
910	                    && existing.getId() < match.getId())) {
911	                    match = existing;
912	                }
913	            }
914	        }
915	        if (match != null) {
916	            owner.setPossibleDuplicate(true);
917	            owner.setPossibleDuplicateOf(match.getId());
918	        }
919	    }
