921	    /**
922	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
923	     * and brackets are stripped. When the number already carries a leading {@code '+'}
924	     * and country code these are kept; a number written in national trunk form (a leading
925	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
926	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
927	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
928	     * after the {@code '+'}, and its national-number length must be valid for the detected
929	     * country code (see {@link #hasValidNationalLength}).
930	     *
931	     * @param telephone the raw telephone value supplied by the client
932	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
933	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
934	     */
935	    private static String toE164(String telephone) {
936	        if (telephone == null) {
937	            return null;
938	        }
939	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
940	        String digits;
941	        if (cleaned.startsWith("+")) {
942	            digits = cleaned.substring(1);
943	        } else if (cleaned.startsWith("0")) {
944	            digits = "61" + cleaned.substring(1);
945	        } else {
946	            digits = "1" + cleaned;
947	        }
948	        if (!digits.matches("[0-9]{8,15}")) {
949	            return null;
950	        }
951	        if (!hasValidNationalLength(digits)) {
952	            return null;
953	        }
954	        return "+" + digits;
955	    }
956	
957	    /**
958	     * Validates the national-number length of an E.164 digit string against its country
959	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
960	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
961	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
962	     *
963	     * @param digits the E.164 digits (without the leading {@code '+'})
964	     * @return {@code true} when the national-number length is valid for the country code
965	     */
966	    private static boolean hasValidNationalLength(String digits) {
967	        if (digits.startsWith("61")) {
968	            return digits.length() - 2 == 9;
969	        }
970	        if (digits.startsWith("1")) {
971	            return digits.length() - 1 == 10;
972	        }
973	        return true;
974	    }
