976	    /**
977	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
978	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
979	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
980	     */
981	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
982	        "NSW", new int[] {2000, 2099},
983	        "VIC", new int[] {3000, 3099},
984	        "QLD", new int[] {4000, 4099});
