986	    /**
987	     * Validates an owner's postcode for creation. A postcode is only ever validated when
988	     * present (an absent postcode is optional and accepted). When present it must be exactly
989	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
990	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
991	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
992	     *
993	     * @param postcode the supplied postcode (never {@code null} here)
994	     * @param city     the owner's city, used to derive the region
995	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
996	     *         (signalling a 400 Bad Request)
997	     */
998	    private static boolean isValidPostcode(String postcode, String city) {
999	        if (!postcode.matches("[0-9]{4}")) {
1000	            return false;
1001	        }
1002	        int[] range = REGION_POSTCODES.get(
1003	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
1004	        if (range == null) {
1005	            return true;
1006	        }
1007	        int value = Integer.parseInt(postcode);
1008	        return value >= range[0] && value <= range[1];
1009	    }
