1011	    /**
1012	     * Disposable email domains that are not accepted for owner creation. An owner whose
1013	     * email domain (compared case-insensitively) is in this set is rejected with a 400
1014	     * Bad Request.
1015	     */
1016	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
1017	        "mailinator.com", "tempmail.com", "guerrillamail.com");
