1019	    /**
1020	     * Normalizes an owner email for creation. A present email must be a syntactically
1021	     * valid address whose domain is not on the disposable-domain blocklist ({@link
1022	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
1023	     *
1024	     * @param email the raw email value supplied by the client (never {@code null} here)
1025	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
1026	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
1027	     */
1028	    private static String normalizeEmail(String email) {
1029	        String trimmed = email.trim();
1030	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
1031	            return null;
