26	    private OwnerLocality() {
27	    }
28	
29	    /**
30	     * Return the canonical region for {@code city}, or {@code "UNKNOWN"} when the city is
31	     * null or not present in the table.
32	     */
33	    public static String forCity(String city) {
34	        return city == null ? "UNKNOWN" : CITY_REGION.getOrDefault(city, "UNKNOWN");
35	    }
36	
37	    /**
38	     * Return the canonical region, preferring the {@code postcode}: if it is a 4-digit code
39	     * that falls inside a known region's range, that region is returned; otherwise fall back
40	     * to the city-to-region table. Returns {@code "UNKNOWN"} when neither resolves a region.
41	     */
42	    public static String forCityAndPostcode(String city, String postcode) {
43	        String byPostcode = forPostcode(postcode);
44	        return byPostcode != null ? byPostcode : forCity(city);
45	    }
46	
47	    /**
48	     * Return the canonical region derived from the {@code postcode} alone (NSW 2000-2099,
49	     * VIC 3000-3099, QLD 4000-4099), or {@code "UNKNOWN"} when the postcode is absent,
50	     * malformed, or in no known range. This is the REGION component of an owner's
51	     * {@code customerCode}.
52	     */
53	    public static String forPostcodeOrUnknown(String postcode) {
54	        String region = forPostcode(postcode);
55	        return region != null ? region : "UNKNOWN";
56	    }
57	
58	    /**
59	     * Return the REGION component of a {@code customerCode} formatted {@code '<REGION>-<HASH8>'},
60	     * i.e. the text before the first {@code '-'}. Returns {@code "UNKNOWN"} when the customer
61	     * code is null or carries no region prefix. This is the owner's derived {@code locality}.
62	     */
63	    public static String regionFromCustomerCode(String customerCode) {
64	        if (customerCode == null) {
65	            return "UNKNOWN";
66	        }
67	        int dash = customerCode.indexOf('-');
68	        return dash > 0 ? customerCode.substring(0, dash) : "UNKNOWN";
69	    }
