71	    /**
72	     * Return the IANA timezone name for the owner's {@code customerCode}, derived from its
73	     * REGION component via the fixed region-to-timezone table (NSW -> Australia/Sydney,
74	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). Returns {@code null} when the
75	     * region is unknown, so the {@code timezone} field is omitted from the response.
76	     */
77	    public static String timezoneFromCustomerCode(String customerCode) {
78	        return REGION_TIMEZONE.get(regionFromCustomerCode(customerCode));
79	    }
