81	    /**
82	     * Compute the single Luhn check digit (0-9) over the digits contained in {@code s}.
83	     * Non-digit characters are ignored; the rightmost digit is doubled first. Kept here,
84	     * alongside the other derived-field helpers, so MapStruct does not treat it as an
85	     * implicit mapping method.
86	     */
87	    public static int luhn(String s) {
88	        int sum = 0;
89	        boolean dbl = true;
90	        for (int i = s.length() - 1; i >= 0; i--) {
91	            char c = s.charAt(i);
92	            if (c < '0' || c > '9') {
93	                continue;
94	            }
95	            int d = c - '0';
96	            if (dbl) {
97	                d *= 2;
98	                if (d > 9) {
99	                    d -= 9;
100	                }
101	            }
102	            sum += d;
103	            dbl = !dbl;
104	        }
105	        return (10 - (sum % 10)) % 10;
106	    }
107	
108	    /**
109	     * Return the canonical region whose postcode range contains {@code postcode}, or
110	     * {@code null} when the postcode is absent, malformed, or in no known range.
111	     */
112	    private static String forPostcode(String postcode) {
113	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
114	            return null;
115	        }
116	        int value = Integer.parseInt(postcode);
117	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
118	            int[] range = entry.getValue();
119	            if (value >= range[0] && value <= range[1]) {
120	                return entry.getKey();
121	            }
122	        }
123	        return null;
124	    }
125	}
